code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] != 1 and (r, c) not in seen:
                seen.add((r, c)); q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] != 1 and (r, c) not in seen:
                seen.add((r, c)); q.append((r, c))
    while q:
        r, c = q.popleft()
        for rr, cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != 1 and (rr,cc) not in seen:
                seen.add((rr,cc)); q.append((rr,cc))
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 and (r,c) not in seen:
                out[r][c] = 4
    return out
'''
